calc.mjs.text:
// Pure pricing arithmetic for a bounce-house / inflatable party rental
// booking. No network, no state: every rate, mile, and minute is an input,
// so the result stays a transparent calculation the operator can check
// against their own truck log and insurance bill rather than a claim about
// what any event "should" cost or whether a site meets code.
//
// The costs a flat "per unit per day" rental rate cannot see, and the ones
// this exists to put back in:
//   - Delivery is a round trip and pickup is a second round trip, even for a
//     same-day booking, because the truck makes the drive twice.
//   - Setup and teardown are paid crew minutes, not included in the rental
//     rate by default.
//   - A generator is a real line item at a site with no outlet in extension-
//     cord reach, which describes most parks and fields.
//   - A water slide or dunk tank commonly needs an attendant on duty for the
//     whole rental window under the operator's own liability policy -- a
//     labor cost with nothing to do with delivery or setup.
//   - General-liability coverage for inflatables is usually priced against
//     the replacement value of the equipment on site, not against the quote,
//     so it scales with the fleet, not the day.

// Common starting daily rates and replacement values by unit type. These are
// ballpark figures to start from, NOT a published tariff, an insurance
// schedule, or a guarantee. Real operators replace them with their own book.
export const UNIT_PRESETS = Object.freeze([
  { id: 'bounce-standard', label: 'Standard bounce house', dailyRate: 150, replacementValue: 1800, wet: false },
  { id: 'bounce-combo', label: 'Bounce house + slide combo', dailyRate: 225, replacementValue: 3200, wet: false },
  { id: 'water-slide', label: 'Water slide', dailyRate: 275, replacementValue: 3800, wet: true },
  { id: 'obstacle-course', label: 'Obstacle course', dailyRate: 350, replacementValue: 5200, wet: false },
  { id: 'dunk-tank', label: 'Dunk tank', dailyRate: 180, replacementValue: 2400, wet: true },
]);

/**
 * Every scalar `calculateQuote` reads off the form, in the order the page lays
 * them out. The fleet table is not here: its fields are derived per row from
 * `UNIT_PRESETS` above.
 *
 * This lived in `index.html` until the shareable link needed it too. A second
 * copy is how a field gets added to the form and quietly left out of the link,
 * so the recipient prices a different booking from the same URL with nothing
 * on screen saying so — the failure `platform/ci/check_shared_link_clears.py`
 * exists to catch, and the copied-constant mistake CLAUDE.md records twice
 * against the front-door mirror. The page and `share.mjs` both import it.
 */
export const COST_IDS = Object.freeze([
  'eventDays', 'setupMinutesPerUnit', 'teardownMinutesPerUnit', 'crewSize', 'laborRate',
  'deliveryFee', 'pickupFee', 'milesOneWay', 'ratePerMile', 'generatorFee',
  'attendantHours', 'attendantRate', 'insuranceRatePct', 'consumablesPerUnit', 'otherCost',
  'overheadRate', 'targetMargin', 'proposedPrice',
]);

/** The three per-unit fields the fleet table renders for each preset. */
export const UNIT_FIELDS = Object.freeze(['quantity', 'dailyRate', 'replacementValue']);

function number(value, name, { min = 0, allowZero = true } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (!allowZero && result === 0) throw new Error(`${name} must be greater than zero`);
  return result;
}

/**
 * Price a bounce-house / inflatable rental booking from the units deployed,
 * the crew time to run them, and the truck's two round trips.
 *
 * @param {object} input
 * @param {Array<{name?: string, quantity: number, dailyRate: number, replacementValue: number, wet?: boolean}>} input.units
 * @param {number} input.eventDays           Calendar days the unit is out.
 *   An overnight rental Friday to Saturday morning is still 1 if it comes
 *   back the next day; a full weekend hold is 2 or more.
 * @param {number} input.setupMinutesPerUnit
 * @param {number} input.teardownMinutesPerUnit
 * @param {number} input.crewSize
 * @param {number} input.laborRate            Per crew member, per hour.
 * @param {number} input.deliveryFee          Flat drop charge.
 * @param {number} input.pickupFee            Flat pickup charge.
 * @param {number} input.milesOneWay          Yard/warehouse to site, one way.
 * @param {number} input.ratePerMile          Loaded truck rate per mile.
 * @param {boolean} input.generatorNeeded     No outlet in extension-cord reach.
 * @param {number} input.generatorFee
 * @param {number} input.attendantHours       Hours a wet-unit attendant is on
 *   duty. Only billed against units flagged `wet`.
 * @param {number} input.attendantRate        Per hour, per wet unit.
 * @param {number} input.insuranceRatePct     General-liability cost as a % of
 *   the deployed fleet's total replacement value, charged per event.
 * @param {number} input.consumablesPerUnit   Stakes, sandbags, tarps, extension cords, blower fuel.
 * @param {number} input.otherCost            Permits, extra staff, cleaning.
 * @param {number} input.overheadRate         Business overhead as a % on direct cost.
 * @param {number} input.targetMargin         Net profit as a % of the final price.
 * @param {number|null} input.proposedPrice   Optional price already on the table.
 */
export function calculateQuote(input) {
  const unitsInput = Array.isArray(input.units) ? input.units : [];
  if (unitsInput.length === 0) throw new Error('Add at least one unit to price');

  const eventDays = number(input.eventDays ?? 0, 'Event days', { min: 0, allowZero: false });
  const setupMinutesPerUnit = number(input.setupMinutesPerUnit ?? 0, 'Setup minutes per unit');
  const teardownMinutesPerUnit = number(input.teardownMinutesPerUnit ?? 0, 'Teardown minutes per unit');
  const crewSize = number(input.crewSize ?? 0, 'Crew size');
  const laborRate = number(input.laborRate ?? 0, 'Labor rate');
  const deliveryFee = number(input.deliveryFee ?? 0, 'Delivery fee');
  const pickupFee = number(input.pickupFee ?? 0, 'Pickup fee');
  const milesOneWay = number(input.milesOneWay ?? 0, 'Miles one way');
  const ratePerMile = number(input.ratePerMile ?? 0, 'Rate per mile');
  const generatorNeeded = Boolean(input.generatorNeeded);
  const generatorFee = number(input.generatorFee ?? 0, 'Generator fee');
  const attendantHours = number(input.attendantHours ?? 0, 'Attendant hours');
  const attendantRate = number(input.attendantRate ?? 0, 'Attendant rate');
  const insuranceRatePct = number(input.insuranceRatePct ?? 0, 'Insurance rate');
  const consumablesPerUnit = number(input.consumablesPerUnit ?? 0, 'Consumables per unit');
  const otherCost = number(input.otherCost ?? 0, 'Other cost');
  const overheadRate = number(input.overheadRate ?? 0, 'Overhead');
  const targetMargin = number(input.targetMargin ?? 0, 'Target margin');
  if (targetMargin >= 100) throw new Error('Target margin must be less than 100%');

  const units = unitsInput.map((unit, index) => {
    const label = unit.name?.trim() || `Unit ${index + 1}`;
    const quantity = number(unit.quantity ?? 0, `${label}: quantity`);
    const dailyRate = number(unit.dailyRate ?? 0, `${label}: daily rate`);
    const replacementValue = number(unit.replacementValue ?? 0, `${label}: replacement value`);
    const wet = Boolean(unit.wet);
    const rental = quantity * dailyRate * eventDays;
    return { name: label, quantity, dailyRate, replacementValue, wet, rental };
  });

  const totalUnits = units.reduce((sum, unit) => sum + unit.quantity, 0);
  const wetUnits = units.reduce((sum, unit) => sum + (unit.wet ? unit.quantity : 0), 0);
  const rentalCost = units.reduce((sum, unit) => sum + unit.rental, 0);
  const totalReplacementValue = units.reduce((sum, unit) => sum + unit.quantity * unit.replacementValue, 0);

  const setupMinutes = totalUnits * setupMinutesPerUnit;
  const teardownMinutes = totalUnits * teardownMinutesPerUnit;
  const laborHours = crewSize * (setupMinutes + teardownMinutes) / 60;
  const laborCost = laborHours * laborRate;

  // Two round trips: one to deliver, one to pick up, even for a same-day
  // booking. A quote that only prices the miles once never sees the return
  // drive for either leg.
  const mileageCost = 4 * milesOneWay * ratePerMile;
  const haulCost = deliveryFee + pickupFee + mileageCost;

  const generatorCost = generatorNeeded ? generatorFee : 0;
  const attendantCost = wetUnits > 0 ? wetUnits * attendantHours * attendantRate : 0;
  const insuranceCost = totalReplacementValue * insuranceRatePct / 100;
  const consumables = totalUnits * consumablesPerUnit;

  const directCost = rentalCost + laborCost + haulCost + generatorCost + attendantCost + insuranceCost + consumables + otherCost;
  const overhead = directCost * overheadRate / 100;
  const totalCost = directCost + overhead;
  const price = totalCost / (1 - targetMargin / 100);
  const profit = price - totalCost;

  const hasProposed = input.proposedPrice !== null && input.proposedPrice !== undefined && input.proposedPrice !== '';
  const proposedPrice = hasProposed ? number(input.proposedPrice, 'Price you are considering') : null;

  return {
    units: units.map(unit => ({
      ...unit,
      costShare: directCost === 0 ? 0 : unit.rental / directCost * 100,
    })),
    totalUnits,
    wetUnits,
    eventDays,
    rentalCost,
    laborHours,
    laborCost,
    mileageCost,
    haulCost,
    generatorCost,
    attendantCost,
    insuranceCost,
    totalReplacementValue,
    consumables,
    otherCost,
    overhead,
    directCost,
    totalCost,
    price,
    profit,
    pricePerUnit: totalUnits === 0 ? null : price / totalUnits,
    breakEvenPrice: totalCost,
    // A wet unit is quoted but no attendant time is budgeted -- a common gap
    // between what the fleet includes and what the labor line actually pays
    // for. This is a flag to check against the operator's own policy, not a
    // determination that an attendant is legally required.
    wetUnitsMissingAttendant: wetUnits > 0 && attendantHours * attendantRate === 0,
    proposed: proposedPrice === null ? null : {
      price: proposedPrice,
      profit: proposedPrice - totalCost,
      margin: proposedPrice === 0 ? 0 : (proposedPrice - totalCost) / proposedPrice * 100,
      belowBreakEven: proposedPrice < totalCost,
    },
  };
}

share.mjs.text:
import { COST_IDS, UNIT_FIELDS, UNIT_PRESETS } from './calc.mjs';

/**
 * A rental quote carries two kinds of state, and both have to travel or the
 * recipient prices a different booking:
 *
 *   - the eighteen scalars in `COST_IDS` (days, crew, haul, insurance, margin);
 *   - the fleet table — quantity, daily rate and replacement value for each of
 *     the five presets.
 *
 * Both lists are imported from `calc.mjs`, never restated. The fleet fields are
 * flattened as `<presetId>.<field>` so the query string stays a flat
 * `URLSearchParams` — no JSON blob in a URL, and an unknown preset id in a
 * crafted link simply finds no home rather than inventing a row.
 */
export const UNIT_PARAM_IDS = Object.freeze(
  UNIT_PRESETS.flatMap(preset => UNIT_FIELDS.map(field => `${preset.id}.${field}`)),
);

/** Every parameter a link may carry, scalars first. */
export const SHARE_PARAMS = Object.freeze([...COST_IDS, 'generatorNeeded', ...UNIT_PARAM_IDS]);

function encodeNumber(params, key, value) {
  // Blank is a real state and is not an absent key: a cost field the sender
  // cleared should arrive cleared, so the recipient sees the same error the
  // sender saw rather than this page's shipped example figure.
  if (value === '') {
    params.set(key, '');
    return;
  }
  const number = Number(value);
  if (Number.isFinite(number) && number >= 0) params.set(key, String(number));
}

export function encodeInputs(input) {
  const params = new URLSearchParams();
  for (const id of COST_IDS) encodeNumber(params, id, input?.[id]);
  params.set('generatorNeeded', input?.generatorNeeded ? '1' : '0');
  for (const preset of UNIT_PRESETS) {
    for (const field of UNIT_FIELDS) {
      encodeNumber(params, `${preset.id}.${field}`, input?.units?.[preset.id]?.[field]);
    }
  }
  return params.toString();
}

function decodeNumber(params, key) {
  if (!params.has(key)) return undefined;
  if (params.get(key) === '') return '';
  const number = Number(params.get(key));
  return Number.isFinite(number) && number >= 0 ? number : undefined;
}

export function decodeInputs(value) {
  const params = new URLSearchParams(String(value || '').replace(/^[?#]/, ''));
  const result = { units: {} };
  for (const id of COST_IDS) {
    const decoded = decodeNumber(params, id);
    if (decoded !== undefined) result[id] = decoded;
  }
  if (params.has('generatorNeeded')) result.generatorNeeded = params.get('generatorNeeded') === '1';
  for (const preset of UNIT_PRESETS) {
    for (const field of UNIT_FIELDS) {
      const decoded = decodeNumber(params, `${preset.id}.${field}`);
      if (decoded === undefined) continue;
      result.units[preset.id] ??= {};
      result.units[preset.id][field] = decoded;
    }
  }
  return result;
}

/** True when a decoded link carried anything at all worth applying. */
export function carriesAnything(decoded) {
  if (!decoded) return false;
  if (COST_IDS.some(id => decoded[id] !== undefined)) return true;
  if (decoded.generatorNeeded !== undefined) return true;
  return Object.keys(decoded.units || {}).length > 0;
}

/**
 * Every field the form owns, written whether or not the link carried it — so a
 * box the sender cleared, or a preset they zeroed out of the fleet, arrives
 * that way instead of keeping whatever the recipient's page was showing.
 *
 * Returned as flat element-id → string pairs, which is what the page writes.
 * See `platform/ci/check_shared_link_clears.py`.
 */
export function formValues(decoded) {
  const values = {};
  for (const id of COST_IDS) {
    values[id] = decoded?.[id] !== undefined ? String(decoded[id]) : '';
  }
  for (const preset of UNIT_PRESETS) {
    const unit = decoded?.units?.[preset.id];
    // A preset absent from the link is absent from the fleet, which is a
    // quantity of zero rather than a blank box: the quantity input has
    // min="0" and drives whether the row is priced at all, so blanking it
    // would read as an invalid form instead of "this unit is not going out".
    values[`qty-${preset.id}`] = unit?.quantity !== undefined ? String(unit.quantity) : '0';
    values[`rate-${preset.id}`] = unit?.dailyRate !== undefined ? String(unit.dailyRate) : String(preset.dailyRate);
    values[`val-${preset.id}`] = unit?.replacementValue !== undefined
      ? String(unit.replacementValue)
      : String(preset.replacementValue);
  }
  values.generatorNeeded = Boolean(decoded?.generatorNeeded);
  return values;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// fleet, the miles, the labor rate, the price, or any other quote input, and
// it never leaves the device -- an operator's pricing is exactly the sort of
// thing that must not be transmitted anywhere.
function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'quote_calculated') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  const today = new Date().toISOString().slice(0, 10);
  const current = JSON.parse(storage.getItem('bounce-house-rental-calculator-usage') || '{}');
  current[event] = (current[event] || 0) + 1;
  current.last_day = today;
  storage.setItem('bounce-house-rental-calculator-usage', JSON.stringify(current));
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem('bounce-house-rental-calculator-usage-opt-out') === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem('bounce-house-rental-calculator-usage'); } catch { /* storage is optional */ }
    try { storage.setItem('bounce-house-rental-calculator-usage-opt-out', '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem('bounce-house-rental-calculator-usage-opt-out'); } catch { /* storage is optional */ }
  }
}
